async function Stock({ slug }: { slug: string }) {
  const stock = await getStock(slug);
  if (stock === 0) return <p className="h-6">Out of stock</p>;
  return (
    <div className="grid gap-2">
      <p className="h-6">{stock < 5 ? `Only ${stock} left` : "In stock"}</p>
      <QuantityPicker max={Math.min(stock, 10)} />
    </div>
  );
}

